/**
 * Cross-runtime phoneme timing parity test (WASM/JS).
 *
 * Loads tests/fixtures/phoneme_timing/golden_matrix.json (Python canonical
 * output) and verifies that this runtime's `durationsToTiming` produces
 * byte-equivalent results, within a tight float tolerance.
 *
 * Spec: docs/spec/phoneme-timing-contract.toml v1.0.
 * Fixture is regenerated by scripts/regenerate_timing_fixture.py.
 */

import { describe, it } from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { dirname, resolve } from "node:path";

import {
  buildPhonemeIdToTokenMap,
  durationsToTiming,
  timingToSrt,
  timingToTsv,
} from "../../src/timing.js";

const __dirname = dirname(fileURLToPath(import.meta.url));
const FIXTURE_PATH = resolve(
  __dirname,
  "../../../../../tests/fixtures/phoneme_timing/golden_matrix.json"
);

const fixture = JSON.parse(readFileSync(FIXTURE_PATH, "utf-8"));

// Tolerance: Python uses 64-bit floats, JS Number is also 64-bit, so the
// arithmetic should agree to <1e-9. Allow 1e-6 to absorb any reordering.
const FLOAT_EPS = 1e-6;

const approxEqual = (actual, expected, eps = FLOAT_EPS) => Math.abs(actual - expected) <= eps;

describe("phoneme timing parity (WASM/JS ↔ canonical Python)", () => {
  it("fixture loads with cases", () => {
    assert.strictEqual(fixture.schema_version, 1);
    assert.ok(Array.isArray(fixture.cases));
    assert.ok(fixture.cases.length > 0, "fixture must have cases");
  });

  for (const caseDef of fixture.cases) {
    it(`case: ${caseDef.name} — ${caseDef.description ?? ""}`, () => {
      const { durations, phoneme_tokens, sample_rate, hop_length } = caseDef.inputs;
      const {
        phonemes: expectedPhonemes,
        total_duration_ms: expectedTotal,
        sample_rate: expectedSampleRate,
        tsv: expectedTsv,
        srt: expectedSrt,
      } = caseDef.expected;

      const result = durationsToTiming(
        durations,
        sample_rate,
        hop_length,
        phoneme_tokens.length > 0 ? phoneme_tokens : null
      );

      assert.strictEqual(result.sample_rate, expectedSampleRate, "sample_rate mismatch");
      assert.strictEqual(
        result.phonemes.length,
        expectedPhonemes.length,
        `phonemes count mismatch: got ${result.phonemes.length}, expected ${expectedPhonemes.length}`
      );

      for (let i = 0; i < expectedPhonemes.length; i++) {
        const got = result.phonemes[i];
        const want = expectedPhonemes[i];
        assert.strictEqual(
          got.phoneme,
          want.phoneme,
          `[${caseDef.name}] phoneme[${i}] token mismatch`
        );
        assert.ok(
          approxEqual(got.start_ms, want.start_ms),
          `[${caseDef.name}] phoneme[${i}].start_ms got=${got.start_ms} want=${want.start_ms}`
        );
        assert.ok(
          approxEqual(got.end_ms, want.end_ms),
          `[${caseDef.name}] phoneme[${i}].end_ms got=${got.end_ms} want=${want.end_ms}`
        );
        assert.ok(
          approxEqual(got.duration_ms, want.duration_ms),
          `[${caseDef.name}] phoneme[${i}].duration_ms got=${got.duration_ms} want=${want.duration_ms}`
        );
      }

      assert.ok(
        approxEqual(result.total_duration_ms, expectedTotal),
        `[${caseDef.name}] total_duration_ms got=${result.total_duration_ms} want=${expectedTotal}`
      );

      // Formatted-output parity, byte for byte. The fixture held only float
      // milliseconds until spec_version 1.2, so the FORMATTING layer went
      // unchecked in every runtime -- rounding at .5 (#681), CRLF on Windows
      // (#683) and a thousands separator in the cue index (#684) were each
      // found by reading code, not by a failing test.
      assert.strictEqual(
        timingToTsv(result),
        expectedTsv,
        `[${caseDef.name}] TSV bytes differ from the fixture`
      );
      assert.strictEqual(
        timingToSrt(result),
        expectedSrt,
        `[${caseDef.name}] SRT bytes differ from the fixture`
      );
    });
  }
});

/**
 * Reverse-map parity (issue #698).
 *
 * The cases above start from resolved token strings, so nothing in them says
 * how phoneme_id_map is turned back into names. The contract said first-wins
 * without defining "first", and the runtimes split three/three -- python / js
 * / csharp iterated in insertion order, cpp / rust / go sorted. Every shipped
 * model is collision-free, so all six agreed byte-for-byte and no test could
 * see it.
 */
describe("reverse map parity (WASM/JS ↔ canonical Python)", () => {
  it("fixture carries reverse_map_cases", () => {
    assert.ok(
      Array.isArray(fixture.reverse_map_cases),
      "fixture has no reverse_map_cases; regenerate with scripts/regenerate_timing_fixture.py"
    );
    assert.ok(fixture.reverse_map_cases.length > 0);
  });

  for (const caseDef of fixture.reverse_map_cases ?? []) {
    it(`reverse map: ${caseDef.name}`, () => {
      const { phoneme_id_map, pua_names } = caseDef.inputs;
      const got = buildPhonemeIdToTokenMap(phoneme_id_map, pua_names);

      // Object keys are strings on both sides, so compare as-is.
      assert.deepStrictEqual(got, caseDef.expected);
    });
  }

  it("includes a mirrored colliding case", () => {
    // Anti-vacuity: without a MIRRORED colliding case key order is
    // unobservable. A collision-free map resolves identically under any
    // iteration order, and a single colliding map can be satisfied by a
    // runtime that happens to receive its keys already sorted.
    const ordersByKeySet = new Map();
    for (const caseDef of fixture.reverse_map_cases ?? []) {
      const idMap = caseDef.inputs.phoneme_id_map;
      const seen = new Set();
      let collides = false;
      for (const ids of Object.values(idMap)) {
        for (const id of ids) {
          if (seen.has(id)) collides = true;
          seen.add(id);
        }
      }
      if (!collides) continue;
      const keys = Object.keys(idMap);
      const keySet = [...keys].sort().join("\u0000");
      const orders = ordersByKeySet.get(keySet) ?? new Set();
      orders.add(keys.join("\u0000"));
      ordersByKeySet.set(keySet, orders);
    }

    assert.ok(
      [...ordersByKeySet.values()].some((orders) => orders.size >= 2),
      "no colliding key set is written in two different orders, so these " +
        "cases cannot detect a runtime that iterates phoneme_id_map in " +
        "insertion order"
    );
  });
});
